def _pushdown_predicates(where: tuple | None) -> list[tuple]:
    """The AND-conjoined predicates safe to evaluate against row-group statistics.

    Only comparisons between one bare column and a column-free expression
    (literals / constant arithmetic), ``IS [NOT] NULL`` on a bare column and
    column-free constant predicates are pushed; OR, NOT, CASE, column-to-column
    comparisons and anything with arithmetic over a column stay row-level.
    """
    pushed: list[tuple] = []
    for conjunct in _and_conjuncts(where):
        tag = conjunct[0]
        if tag == "cmp":
            left, right = conjunct[2], conjunct[3]
            left_col = left[0] == "column"
            right_col = right[0] == "column"
            if left_col and right_col:
                continue
            if left_col and not _bound_node_has_column(right):
                pushed.append(conjunct)
            elif right_col and not _bound_node_has_column(left):
                pushed.append(conjunct)
            elif not left_col and not right_col:
                pushed.append(conjunct)
        elif tag == "isnull" and conjunct[1][0] == "column":
            pushed.append(conjunct)
        elif not _bound_node_has_column(conjunct):
            pushed.append(conjunct)
    return pushed

