def _predicate_possible(node: tuple, stats: Mapping, group_rows: int) -> bool:
    """Whether ``node`` could evaluate to TRUE for any row in the group."""
    tag = node[0]
    if tag == "isnull":
        column = node[1]
        entry = stats[column[1]]
        if node[2]:  # IS NOT NULL
            return entry["null_count"] < group_rows
        return entry["null_count"] > 0
    if tag == "cmp":
        left, right = node[2], node[3]
        if left[0] == "column" and right[0] != "column":
            return _comparison_possible(node[1], stats[left[1]], right, True, group_rows)
        if right[0] == "column" and left[0] != "column":
            return _comparison_possible(node[1], stats[right[1]], left, False, group_rows)
        # Both sides are column-free constants: evaluate once, three-valued.
        return _eval(node, ()) is True
    # A non-column constant predicate of another shape.
    return _eval(node, ()) is True

